import{_ as e,o as n,c as s,a3 as t}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"实时语音 Agent","description":"设计实时语音 Agent 的音频链路、会话事件、VAD 与轮次、打断、延迟预算、工具调用、电话集成、安全和评测。","frontmatter":{"title":"实时语音 Agent","description":"设计实时语音 Agent 的音频链路、会话事件、VAD 与轮次、打断、延迟预算、工具调用、电话集成、安全和评测。","verified_at":"2026-07-31","source":["https://www.w3.org/TR/webrtc/","https://www.w3.org/TR/mediacapture-streams/","https://www.rfc-editor.org/rfc/rfc8831","https://www.w3.org/TR/WCAG22/"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/architecture/domain-agent-architectures/voice-realtime-agent.md","filePath":"py-agent/architecture/domain-agent-architectures/voice-realtime-agent.md","lastUpdated":1786083160000}'),i={name:"py-agent/architecture/domain-agent-architectures/voice-realtime-agent.md"};function r(l,a,p,o,c,d){return n(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="实时语音-agent" tabindex="-1">实时语音 Agent <a class="header-anchor" href="#实时语音-agent" aria-label="Permalink to &quot;实时语音 Agent&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>实时语音 Agent 在持续音频会话中理解、回应、调用工具并处理用户打断。与文字聊天相比，它受端到端延迟、噪声、轮次判断、音频传输和不可回看的即时体验影响；错误确认和隐私边界也更重要。</p><p>传输协议、断线续传和应用事件契约见<a href="/py-agent/application/services-api/streaming-realtime-communication">流式与实时通信</a>；高风险语音动作仍使用<a href="/py-agent/architecture/technology-product-design/human-in-loop-trust-design">人在回路与信任设计</a>中的参数绑定确认。本章关注持续音频特有的轮次、播放与打断状态。</p><h2 id="_1-任务边界" tabindex="-1">1. 任务边界 <a class="header-anchor" href="#_1-任务边界" aria-label="Permalink to &quot;1. 任务边界&quot;">​</a></h2><h3 id="_1-1-语音问答" tabindex="-1">1.1 语音问答 <a class="header-anchor" href="#_1-1-语音问答" aria-label="Permalink to &quot;1.1 语音问答&quot;">​</a></h3><p>实时回答信息，工具多为只读。核心是低延迟、准确转写和简洁口语结果。</p><h3 id="_1-2-业务办理" tabindex="-1">1.2 业务办理 <a class="header-anchor" href="#_1-2-业务办理" aria-label="Permalink to &quot;1.2 业务办理&quot;">​</a></h3><p>预约、客服、订单和外呼，涉及身份验证、结构化参数、高风险确认和业务终态。</p><h3 id="_1-3-实时陪伴-辅助" tabindex="-1">1.3 实时陪伴/辅助 <a class="header-anchor" href="#_1-3-实时陪伴-辅助" aria-label="Permalink to &quot;1.3 实时陪伴/辅助&quot;">​</a></h3><p>持续会话、情绪和个性化可能增加敏感风险，不能暗示人类关系或专业资格。</p><h3 id="_1-4-不适用" tabindex="-1">1.4 不适用 <a class="header-anchor" href="#_1-4-不适用" aria-label="Permalink to &quot;1.4 不适用&quot;">​</a></h3><p>复杂表格、长引用和需精确审阅的内容应切换屏幕/文本渠道。语音不应强迫用户在听觉记忆中确认长金额或法律条款。</p><h2 id="_2-两种处理架构" tabindex="-1">2. 两种处理架构 <a class="header-anchor" href="#_2-两种处理架构" aria-label="Permalink to &quot;2. 两种处理架构&quot;">​</a></h2><h3 id="_2-1-级联管线" tabindex="-1">2.1 级联管线 <a class="header-anchor" href="#_2-1-级联管线" aria-label="Permalink to &quot;2.1 级联管线&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Audio -&gt; VAD -&gt; ASR -&gt; Text Agent/LLM -&gt; TTS -&gt; Audio</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>中间 Transcript 可观察、可独立评测，模型和语音组件可替换；每阶段增加延迟，副语言信息可能丢失。</p><h3 id="_2-2-speech-to-speech" tabindex="-1">2.2 Speech-to-Speech <a class="header-anchor" href="#_2-2-speech-to-speech" aria-label="Permalink to &quot;2.2 Speech-to-Speech&quot;">​</a></h3><p>实时模型直接处理/生成音频，交互自然、延迟潜力低；中间语义、转写与工具对齐可能更依赖供应商事件协议。</p><h3 id="_2-3-混合" tabindex="-1">2.3 混合 <a class="header-anchor" href="#_2-3-混合" aria-label="Permalink to &quot;2.3 混合&quot;">​</a></h3><p>实时模型负责对话，独立 Transcript、Policy 和工具网关提供审计与确定控制。选择应以真实噪声、语言、工具和延迟评测为准。</p><h2 id="_3-会话与传输" tabindex="-1">3. 会话与传输 <a class="header-anchor" href="#_3-会话与传输" aria-label="Permalink to &quot;3. 会话与传输&quot;">​</a></h2><h3 id="_3-1-webrtc" tabindex="-1">3.1 WebRTC <a class="header-anchor" href="#_3-1-webrtc" aria-label="Permalink to &quot;3.1 WebRTC&quot;">​</a></h3><p>适合浏览器/移动实时音视频，提供媒体轨、拥塞控制、NAT 穿越和安全传输。信令由应用另行实现；WebRTC API 不规定业务会话协议。</p><h3 id="_3-2-websocket" tabindex="-1">3.2 WebSocket <a class="header-anchor" href="#_3-2-websocket" aria-label="Permalink to &quot;3.2 WebSocket&quot;">​</a></h3><p>适合服务到服务或可控客户端传输音频块/事件，实现简单；媒体拥塞、抖动和设备处理需要应用承担。</p><h3 id="_3-3-电话网络" tabindex="-1">3.3 电话网络 <a class="header-anchor" href="#_3-3-电话网络" aria-label="Permalink to &quot;3.3 电话网络&quot;">​</a></h3><p>PSTN/SIP 网关引入编码、窄带音质、DTMF、转接、录音和号码合规。供应商回调可能重复或乱序，按事件 ID 幂等。</p><h3 id="_3-4-会话身份" tabindex="-1">3.4 会话身份 <a class="header-anchor" href="#_3-4-会话身份" aria-label="Permalink to &quot;3.4 会话身份&quot;">​</a></h3><p>每个连接映射受认证 Session 和租户，重连使用短期令牌恢复。网络连接 ID 不等于业务会话或用户身份。</p><h2 id="_4-音频输入" tabindex="-1">4. 音频输入 <a class="header-anchor" href="#_4-音频输入" aria-label="Permalink to &quot;4. 音频输入&quot;">​</a></h2><h3 id="_4-1-采集" tabindex="-1">4.1 采集 <a class="header-anchor" href="#_4-1-采集" aria-label="Permalink to &quot;4.1 采集&quot;">​</a></h3><p>申请麦克风权限并明确用途；处理设备切换、静音和权限撤销。浏览器的回声消除、降噪和自动增益会影响信号，记录实际约束。</p><h3 id="_4-2-编码" tabindex="-1">4.2 编码 <a class="header-anchor" href="#_4-2-编码" aria-label="Permalink to &quot;4.2 编码&quot;">​</a></h3><p>明确采样率、通道、Sample Format、Codec 和帧时长。任一端解释不一致会产生变速、噪声或无法解码。</p><h3 id="_4-3-抖动与丢包" tabindex="-1">4.3 抖动与丢包 <a class="header-anchor" href="#_4-3-抖动与丢包" aria-label="Permalink to &quot;4.3 抖动与丢包&quot;">​</a></h3><p>Jitter Buffer 平滑网络变化但增加延迟。监控丢包、往返时间、抖动和音频间隙，不能只看模型延迟。</p><h3 id="_4-4-分块" tabindex="-1">4.4 分块 <a class="header-anchor" href="#_4-4-分块" aria-label="Permalink to &quot;4.4 分块&quot;">​</a></h3><p>帧太小增加开销，太大增加响应延迟。传输块边界不等于语义句子，ASR/VAD 管理跨块状态。</p><h2 id="_5-vad-与轮次" tabindex="-1">5. VAD 与轮次 <a class="header-anchor" href="#_5-vad-与轮次" aria-label="Permalink to &quot;5. VAD 与轮次&quot;">​</a></h2><h3 id="_5-1-voice-activity-detection" tabindex="-1">5.1 Voice Activity Detection <a class="header-anchor" href="#_5-1-voice-activity-detection" aria-label="Permalink to &quot;5.1 Voice Activity Detection&quot;">​</a></h3><p>VAD 判断有声/静音，用于开始和结束候选。噪声、停顿、口音和音乐会产生误判。</p><h3 id="_5-2-turn-detection" tabindex="-1">5.2 Turn Detection <a class="header-anchor" href="#_5-2-turn-detection" aria-label="Permalink to &quot;5.2 Turn Detection&quot;">​</a></h3><p>轮次结束不仅由静音长度决定，还可结合语义、语调、用户设置和最大等待。太短会打断用户，太长会让响应迟钝。</p><h3 id="_5-3-push-to-talk" tabindex="-1">5.3 Push-to-Talk <a class="header-anchor" href="#_5-3-push-to-talk" aria-label="Permalink to &quot;5.3 Push-to-Talk&quot;">​</a></h3><p>在嘈杂、高风险或隐私场景提供按键说话作为确定替代。它牺牲自然性但降低轮次误判。</p><h3 id="_5-4-端点确认" tabindex="-1">5.4 端点确认 <a class="header-anchor" href="#_5-4-端点确认" aria-label="Permalink to &quot;5.4 端点确认&quot;">​</a></h3><p>金额、地址、姓名等关键实体转写后复述/显示确认。不要让低置信 ASR 直接触发写工具。</p><h2 id="_6-打断与-barge-in" tabindex="-1">6. 打断与 Barge-in <a class="header-anchor" href="#_6-打断与-barge-in" aria-label="Permalink to &quot;6. 打断与 Barge-in&quot;">​</a></h2><p>用户在 Agent 播放时说话，应停止或 Duck TTS、取消未需要的生成，并开始新输入。必须区分背景声音和真实打断。</p><p>会话状态记录用户实际听到的音频范围；未播放完的回答不能全部写入“已告知用户”的历史。工具若已经执行，打断无法撤销，需明确告知和补偿。</p><p>打断事件从客户端/音频层传播到模型、TTS 和工具 Controller，但高风险不可取消动作应在执行前确认，而不是依赖取消抢救。</p><h2 id="_7-实时事件协议" tabindex="-1">7. 实时事件协议 <a class="header-anchor" href="#_7-实时事件协议" aria-label="Permalink to &quot;7. 实时事件协议&quot;">​</a></h2><p>内部稳定事件可包括：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>session.started</span></span>
<span class="line"><span>audio.input.started / stopped</span></span>
<span class="line"><span>transcript.partial / final</span></span>
<span class="line"><span>response.started</span></span>
<span class="line"><span>audio.output.delta / completed</span></span>
<span class="line"><span>tool.call.proposed / approved / completed</span></span>
<span class="line"><span>response.cancelled</span></span>
<span class="line"><span>session.error / ended</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>每个事件有 <code>session_id</code>、<code>item_id</code>、序列、时间和状态。Partial Transcript 可被修正，不能提前写入业务事实；音频 Delta 的分块粒度不是稳定语义。</p><h2 id="_8-延迟预算" tabindex="-1">8. 延迟预算 <a class="header-anchor" href="#_8-延迟预算" aria-label="Permalink to &quot;8. 延迟预算&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>T_response = capture/end-of-turn</span></span>
<span class="line"><span>           + network uplink</span></span>
<span class="line"><span>           + ASR/prefill</span></span>
<span class="line"><span>           + model first output</span></span>
<span class="line"><span>           + TTS first audio</span></span>
<span class="line"><span>           + downlink/playout</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>分别测用户停止说话到首音频、打断到停止播放、工具等待和总任务完成。流式 ASR、模型和 TTS 可以流水线重叠，但过早合成可能基于随后被修正的文本。</p><p>优化顺序：减少错误轮次、复用连接、就近区域、控制上下文、流式管线、缓存固定音频、将长工具转后台。不能靠删除确认牺牲安全来降延迟。</p><h2 id="_9-工具调用" tabindex="-1">9. 工具调用 <a class="header-anchor" href="#_9-工具调用" aria-label="Permalink to &quot;9. 工具调用&quot;">​</a></h2><h3 id="_9-1-对话填槽" tabindex="-1">9.1 对话填槽 <a class="header-anchor" href="#_9-1-对话填槽" aria-label="Permalink to &quot;9.1 对话填槽&quot;">​</a></h3><p>把日期、订单、地址等保存为结构化 Slot，来源和确认状态明确。用户修正时更新特定字段，不从全 Transcript 猜最终值。</p><h3 id="_9-2-等待策略" tabindex="-1">9.2 等待策略 <a class="header-anchor" href="#_9-2-等待策略" aria-label="Permalink to &quot;9.2 等待策略&quot;">​</a></h3><p>短工具等待可播放简短真实状态；长任务转后台或告知预计时间。不要循环播放虚假“马上完成”。</p><h3 id="_9-3-高风险确认" tabindex="-1">9.3 高风险确认 <a class="header-anchor" href="#_9-3-高风险确认" aria-label="Permalink to &quot;9.3 高风险确认&quot;">​</a></h3><p>通过语音复述关键参数，并在可用时同步屏幕/短信确认。确认令牌绑定具体参数；声音相似不是可靠身份认证。</p><h3 id="_9-4-转人工" tabindex="-1">9.4 转人工 <a class="header-anchor" href="#_9-4-转人工" aria-label="Permalink to &quot;9.4 转人工&quot;">​</a></h3><p>移交摘要包含已验证身份、目标、字段、已执行动作、失败和 Transcript 引用。Agent 停止自动行动，人工获得明确会话所有权。</p><h2 id="_10-状态与记忆" tabindex="-1">10. 状态与记忆 <a class="header-anchor" href="#_10-状态与记忆" aria-label="Permalink to &quot;10. 状态与记忆&quot;">​</a></h2><p>分开保存音频 Artifact、Partial/Final Transcript、对话 Item、业务 Slot、工具状态和长期记忆。原始音频和 Transcript 的保留、访问与删除可能不同。</p><p>只将 Final Transcript 或明确用户修正进入长期状态；对口音/噪声下不确定实体保留候选。记忆应可查看、纠正和关闭。</p><h2 id="_11-安全与隐私" tabindex="-1">11. 安全与隐私 <a class="header-anchor" href="#_11-安全与隐私" aria-label="Permalink to &quot;11. 安全与隐私&quot;">​</a></h2><p>开始录音/转写时明确提示，遵守地区和行业关于录音、同意与外呼的要求。音频可包含生物特征和旁观者信息，默认最小保留。</p><p>语音内容同样可能 Prompt Injection；来电号码和声音不能单独证明身份。DTMF、账户验证或其他正式认证与 Agent 内容分离。</p><p>限制工具、外呼目的地、转接和数据播报。公共环境不要朗读完整敏感信息；提供耳机/屏幕或身份再验证。</p><p>合成声音需要披露 AI 身份，避免未经授权模仿个人。生成和播放内容执行安全策略。</p><h2 id="_12-可靠性与降级" tabindex="-1">12. 可靠性与降级 <a class="header-anchor" href="#_12-可靠性与降级" aria-label="Permalink to &quot;12. 可靠性与降级&quot;">​</a></h2><p>网络变差时降低码率、提示重说、切文本或回拨；ASR/模型/TTS 单点失败分别处理。重连恢复已确认 Slot 和任务，但不重复已完成工具。</p><p>为会话设置时长、静音、Token、工具和费用上限。服务过载时优先保持正在通话、限制新会话，并提供安全失败或人工入口。</p><h2 id="_13-评测" tabindex="-1">13. 评测 <a class="header-anchor" href="#_13-评测" aria-label="Permalink to &quot;13. 评测&quot;">​</a></h2><p>阶段指标：ASR WER/实体准确、端点误切、TTS 可懂度、丢包与延迟；端到端指标：任务成功、关键字段、打断成功、工具安全、转人工、每成功任务成本。</p><p>覆盖噪声、口音、语速、重叠说话、静音、设备切换、网络抖动、多语言、数字/地址和高风险确认。自动指标结合真人听测与无障碍测试。</p><h2 id="_14-贯穿案例-预约上门服务" tabindex="-1">14. 贯穿案例：预约上门服务 <a class="header-anchor" href="#_14-贯穿案例-预约上门服务" aria-label="Permalink to &quot;14. 贯穿案例：预约上门服务&quot;">​</a></h2><p>场景：已登录用户通过语音预约第二天下午的上门维修，写工具 <code>appointment.create</code> 必须在日期、时间和地址均被明确确认后调用。</p><h3 id="_14-1-轮次与-slot" tabindex="-1">14.1 轮次与 Slot <a class="header-anchor" href="#_14-1-轮次与-slot" aria-label="Permalink to &quot;14.1 轮次与 Slot&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户 final transcript：明天下午来修空调</span></span>
<span class="line"><span>解析 Slot：</span></span>
<span class="line"><span>  date = 2026-08-07（已解析，待确认）</span></span>
<span class="line"><span>  time = null</span></span>
<span class="line"><span>  address = 上海市徐汇区示例路 8 号（来自已认证账户，待确认）</span></span>
<span class="line"><span>Agent：下午 2 点或 4 点都可以，你选哪个？</span></span>
<span class="line"><span>用户 final transcript：两点</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>Partial Transcript 只用于实时显示，只有 Final Transcript 和用户修正进入 Slot。模型不能因为账户里有默认地址就直接调用工具。</p><h3 id="_14-2-打断" tabindex="-1">14.2 打断 <a class="header-anchor" href="#_14-2-打断" aria-label="Permalink to &quot;14.2 打断&quot;">​</a></h3><p>Agent 开始播放“我将为你预约明天下午两点……”，用户在播放 620 毫秒后说“等等，改成四点”。系统产生：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>audio.input.started</span></span>
<span class="line"><span>response.cancelled(item_id=r-21)</span></span>
<span class="line"><span>audio.output stopped_at=620ms</span></span>
<span class="line"><span>slot.updated(time=16:00, source=user_correction)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>State 只记录用户实际听到“我将为你预约”，不把未播放的日期和时间视为已告知。原两点的动作提案与确认哈希同时失效。</p><h3 id="_14-3-确认与执行" tabindex="-1">14.3 确认与执行 <a class="header-anchor" href="#_14-3-确认与执行" aria-label="Permalink to &quot;14.3 确认与执行&quot;">​</a></h3><p>Agent 重新复述：“确认预约 2026 年 8 月 7 日 16:00，地址为上海市徐汇区示例路 8 号吗？”用户回答“确认”后，服务端把身份、三个 Slot、策略版本和一次性随机值绑定为确认令牌。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tool.call.proposed  appointment.create / 2026-08-07 16:00</span></span>
<span class="line"><span>tool.call.approved  token=confirm-92</span></span>
<span class="line"><span>tool.call.completed appointment_id=AP-7781</span></span>
<span class="line"><span>audio.output.completed</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>最终语音和同步文字都显示预约编号 <code>AP-7781</code>。若工具响应丢失，系统使用幂等键查询预约状态，不再次创建；若网络持续变差，则保留已确认 Slot，转为文字或人工渠道。</p><p>这个案例同时经过 VAD/Turn Detection、Final Transcript、Slot 修正、Barge-in、参数绑定确认、幂等工具和多通道结果，说明实时语音不是给文字 Agent 简单加一层 ASR/TTS。</p><h2 id="_15-常见误区" tabindex="-1">15. 常见误区 <a class="header-anchor" href="#_15-常见误区" aria-label="Permalink to &quot;15. 常见误区&quot;">​</a></h2><ol><li><strong>把文字 Agent 加 ASR/TTS 就完成</strong>：轮次、打断和音频状态未设计。</li><li><strong>静音等于说完</strong>：自然停顿会被截断。</li><li><strong>Partial Transcript 是事实</strong>：它可能随流更新。</li><li><strong>声音或来电号就是身份</strong>：容易伪造且权限不足。</li><li><strong>模型快就是体验快</strong>：采集、网络、TTS 和播放同样在关键路径。</li></ol><p>实时语音 Agent 的核心是实时状态协调：系统必须知道用户何时在说、听到了什么、哪些字段已确认、哪个动作已经发生，并在几百毫秒级交互中仍保持权限、可取消性和可恢复性。</p>`,100)])])}const b=e(i,[["render",r]]);export{u as __pageData,b as default};
